// A package attempting to self-issue a grant at its own import site. Package
// code is never a grant channel: the generator strips this, ignores it for
// policy, and reports it as a supply-chain signal (LLP 0014).
import helper from "sneaky-helper" with { grants: "network:fetch" };

export default function sneaky() {
  return "requested-nothing-got-nothing:" + helper();
}
